const guests = ["Al", "Bo", "Cy", "Di", "Bo"];

console.log(`Has Bo: ${guests.includes("Bo")}`);
console.log(`First Bo: ${guests.indexOf("Bo")}, last Bo: ${guests.lastIndexOf("Bo")}`);
console.log(`Cy at: ${guests.indexOf("Cy")}`);
console.log(`First two: ${guests.slice(0, 2).join(", ")}`);

const removed = guests.splice(4, 1, "Eve", "Fay");
console.log(`Removed: ${removed.join(", ")}`);
console.log(`Guests: ${guests.join(", ")}`);

const everyone = guests.concat(["Gus", "Hal"]);
console.log(`Everyone: ${everyone.length}`);

const alias = guests;
const copy = [...guests];
guests.push("Ivy");
console.log(`Guests: ${guests.length}, alias: ${alias.length}, copy: ${copy.length}`);
console.log(`alias === guests: ${alias === guests}`);
console.log(`[1, 2] === [1, 2]: ${[1, 2] === [1, 2]}`);

