practice.solution:
const shelf = ["Dune", "Emma", "Ulysses", "Emma", "Hamlet"];
const shelf2 = ["Walden", "Rebecca"];

console.log(`Has Emma: ${shelf.includes("Emma")}`);
console.log(`Dune at: ${shelf.indexOf("Dune")}, last Emma at: ${shelf.lastIndexOf("Emma")}, Odyssey at: ${shelf.indexOf("Odyssey")}`);
console.log(`Last three: ${shelf.slice(-3).join(", ")}`);

shelf.splice(1, 0, "Ivanhoe");
console.log(`Shelf: ${shelf.join(", ")}`);
const combined = shelf.concat(shelf2);
console.log(`Combined: ${combined.length}`);

const alias = shelf;
const copy = shelf.slice();
shelf.pop();
console.log(`Shelf: ${shelf.length}, alias: ${alias.length}, copy: ${copy.length}`);
console.log(`copy === shelf: ${copy === shelf}`);

